PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, cache_key TEXT UNIQUE NOT NULL, body TEXT NOT NULL, created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS quota (id INTEGER PRIMARY KEY, at REAL NOT NULL, tokens INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS contributions (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('project','resource','topic','reply')), owner TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, body TEXT NOT NULL, url TEXT NOT NULL DEFAULT '', parent TEXT REFERENCES contributions(id), evidence TEXT NOT NULL DEFAULT '', created REAL NOT NULL, hidden INTEGER NOT NULL DEFAULT 0, consent INTEGER NOT NULL DEFAULT 0, credit TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS votes (user_id TEXT NOT NULL REFERENCES users(id), item TEXT NOT NULL REFERENCES contributions(id), value INTEGER NOT NULL CHECK(value IN (-1,1)), PRIMARY KEY(user_id,item));
CREATE TABLE IF NOT EXISTS abuse (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), item TEXT NOT NULL REFERENCES contributions(id), reason TEXT NOT NULL, resolved INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS social_consent (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), report TEXT NOT NULL, finding TEXT NOT NULL, proof_url TEXT NOT NULL, credit TEXT NOT NULL, consent_at REAL NOT NULL, verified_by TEXT REFERENCES users(id), verification TEXT NOT NULL DEFAULT '', revoked INTEGER NOT NULL DEFAULT 0);
PRAGMA user_version=1;
